//! OneDesk protocol: the only contract between the interface and a worker process
//! (kernel-design §12). Rust is the source of truth; TypeScript types are generated by
//! `pnpm gen:types` into `src/workbench/protocol/generated/` and checked by `pnpm check:types`.
//!
//! Wire format: one JSON object per line.
//!   request   `{ id, method, params, client? }`
//!   response  `{ id, result }` or `{ id, error }`
//!   event     `{ topic, payload?, client? }`            (no `id`)
//! The first request on a connection must be `hello`.
//!
//! This crate holds types only. It knows no plugin, no kind and no interface text.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};
use serde_json::Value;
use serde_with::skip_serializing_none;
use ts_rs::TS;

/// Both ends compare this in `hello`; a mismatch is `ErrorCode::VersionMismatch`.
pub const PROTOCOL_VERSION: &str = "1";

pub type JsonMap = BTreeMap<String, Value>;

/// Method names. Week 1 implements exactly these; everything else answers `unknownMethod`.
pub mod method {
    pub const HELLO: &str = "hello";
    pub const WORKSPACE_INFO: &str = "workspace.info";
    pub const TREE_LIST: &str = "tree.list";
    pub const TREE_CHILDREN: &str = "tree.children";
    pub const TREE_PATH: &str = "tree.path";
    pub const TREE_MOVE: &str = "tree.move";
    pub const TREE_CREATE_GROUP: &str = "tree.createGroup";
    pub const TREE_RENAME: &str = "tree.rename";
    pub const RESOURCE_GET: &str = "resource.get";
    pub const RESOURCE_DELETE: &str = "resource.delete";
    pub const PAGE_RESOLVE: &str = "page.resolve";
    pub const PAGE_SAVE: &str = "page.save";
    pub const COMMAND_NEW_ITEMS: &str = "command.newItems";
    pub const COMMAND_EXECUTE: &str = "command.execute";
    pub const PLUGIN_GRANTS: &str = "plugin.grants";
    pub const PLUGIN_GRANT_FOLDER: &str = "plugin.grantFolder";
    pub const PLUGIN_REVOKE_FOLDER: &str = "plugin.revokeFolder";
    pub const UI_GET: &str = "ui.get";
    pub const UI_SET: &str = "ui.set";
}

/// Event topics. Events only say "this changed, read it again" (§12).
pub mod topic {
    /// `tree:<treeId>`: nodes of this tree changed.
    pub const TREE: &str = "tree:";
    /// `resource:<id>`: this resource changed or was deleted.
    pub const RESOURCE: &str = "resource:";
    /// Plugin state or grants changed.
    pub const PLUGINS: &str = "plugins";
    /// Payload is a `CommandEffect` a plugin asked for through `host.ui`; `client` names the receiver.
    pub const UI: &str = "ui";
    /// Sent by the main process, not the worker. Payload `ConnectionState`. After `restored`
    /// the interface re-reads everything.
    pub const CONNECTION: &str = "connection";
}

/* ------------------------------------------------------------------ wire */

#[skip_serializing_none]
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export, optional_fields)]
pub struct Request {
    pub id: u64,
    pub method: String,
    #[serde(default)]
    pub params: Value,
    /// Client id (one per window or browser). Set by the main process when forwarding; the
    /// kernel keeps interface state per client (§9.2) and treats the actor as the local user.
    pub client: Option<String>,
}

#[skip_serializing_none]
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export, optional_fields)]
pub struct Response {
    pub id: u64,
    pub result: Option<Value>,
    pub error: Option<ProtocolError>,
}

#[skip_serializing_none]
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export, optional_fields)]
pub struct EventMessage {
    pub topic: String,
    pub payload: Option<Value>,
    /// Only this client should receive it; absent = every client of the workspace.
    pub client: Option<String>,
}

/// No interface text (§11): the shell turns `code` + `params` into a sentence.
#[skip_serializing_none]
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[ts(export, optional_fields)]
pub struct ProtocolError {
    pub code: ErrorCode,
    #[serde(default)]
    pub params: BTreeMap<String, String>,
    /// For logs and developers only; never shown as the message.
    pub detail: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum ErrorCode {
    VersionMismatch,
    UnknownMethod,
    InvalidParams,
    /// Target, resource, node, tree or plugin does not exist.
    NotFound,
    /// The same field was changed by someone else after `basis` (§4).
    Conflict,
    /// A permission or policy check refused the call (§1.5 "refuse first").
    Denied,
    /// The command is well-formed but not allowed here (bad parent, cycle, empty name…).
    Invalid,
    /// Valid in the design, not implemented in this build.
    Unsupported,
    /// The plugin threw, returned an invalid view, or is not loaded.
    PluginError,
    PluginTimeout,
    /// The worker died while the request was in flight (set by the main process).
    WorkerGone,
    Internal,
}

